"""D2 task pages: source-based localization and a separate third-party player."""
from pathlib import Path
from html import escape
from site_analytics import write_html
from play_recommendations import recommendations,stylesheet

ROOT=Path(__file__).resolve().parents[1]
P='/d2-survivors/'
ZH=P+'zh/localization/'
GAME='https://play.d2survivors.org/play/'
ORIGINAL='https://d2survivors.lol/play/'
PATCH='https://jtnhrbpvvm-spec.github.io/taiwan_game2/D2%E4%BF%AE%E6%94%B9%E7%89%88/'
AD='<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-8830315294299920" crossorigin="anonymous"></script>'

def ext(url,label):return f'<a href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">{label} ↗</a>'
def ref(i):return f'<sup class="ref"><a href="#source-{i}" aria-label="Source {i}">[{i}]</a></sup>'
def shell(route,title,desc,body,lang='en',play=False):
 nav=f'<a href="{P}play/">Play D2 Survivors</a><a href="{ZH}" lang="zh-Hant">繁體中文化</a><a href="/#wiki-start">Related games</a>'
 return stylesheet(f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="https://megabonk.org{route}"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:type" content="article"><meta property="og:url" content="https://megabonk.org{route}"><meta property="og:image" content="https://megabonk.org/assets/d2-survivors/{'run' if play else 'original-menu'}-1280.webp"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/assets/pokebonk/site.css"><link rel="stylesheet" href="/assets/guide-article-layout.css"><link rel="stylesheet" href="/assets/d2-survivors/site.css">{('<link rel="stylesheet" href="/assets/poke-survivor/play.css"><script defer src="/assets/d2-survivors/play.js"></script>' if play else '')}{AD}</head><body class="guide-layout{' ps-play-page' if play else ''}"><a class="skip" href="#main">Skip to content</a><header class="top"><div class="wrap"><a class="brand" href="/"><span>Megabonk.org<small>Independent games &amp; guides</small></span></a><nav class="desktop-nav" aria-label="Main navigation">{nav}</nav><details class="mobile-nav"><summary>Menu ☰</summary><nav class="mobile-links" aria-label="Mobile navigation">{nav}</nav></details></div></header><main class="wrap" id="main">{body}</main><footer class="footer"><div class="wrap footer-grid"><div><strong>Find your next run.</strong><p>Independent editorial by Megabonk.org. Not affiliated with framara or Blizzard Entertainment. Game names and artwork belong to their owners.</p><a href="/#wiki-start">More game guides →</a></div><nav aria-label="Site information"><a href="/about/">About</a><a href="/contact/">Contact</a><a href="/privacy-policy#d2-survivors">Privacy</a></nav></div></footer></body></html>''')

def figure(stem,alt,caption,source):
 return f'<figure class="game-image" data-game-image="d2-{stem}"><a href="/assets/d2-survivors/{stem}-1280.webp" target="_blank" rel="noopener"><img src="/assets/d2-survivors/{stem}-800.webp" srcset="/assets/d2-survivors/{stem}-800.webp 800w, /assets/d2-survivors/{stem}-1280.webp 1280w" sizes="(max-width:800px) calc(100vw - 36px), 1000px" width="1280" height="900" loading="lazy" alt="{alt}"></a><figcaption>{caption} {ref(source)} <a href="/assets/d2-survivors/{stem}-1280.webp" target="_blank" rel="noopener" class="image-zoom">Open full image ↗</a></figcaption></figure>'

def localization():
 parts=[('source','先確認你開的是哪個遊戲',f'<p>本頁對應 framara 的 D2 Survivors，原作入口是 {ext(ORIGINAL,"D2 Survivors · 原作")}。這是非官方暗黑 II 同人遊戲，不是《暗黑破壞神 II：獄火重生》本體漢化。原站目前提供英文與韓文；下文中文工具由另一位玩家維護，不是遊戲內建中文。{ref(1)}{ref(2)}</p><p>若你用的是其他作者的同名 Windows 專案，或本站的第三方遊戲窗口，先回原作辨認來源；不要把同名專案、存檔或補丁當成通用。本站不代管中文工具，也不自動替遊戲安裝它。</p>'),
 ('choose','瀏覽器、Windows 安裝版：選對路徑',f'<div class="table-wrap" tabindex="0" role="region" aria-label="中文化路徑選擇"><table><thead><tr><th>你在哪裡玩</th><th>下一步</th><th>先確認</th></tr></thead><tbody><tr><td>原作的電腦瀏覽器頁面</td><td>作者的瀏覽器書籤教學</td><td>書籤作用在目前開啟的遊戲頁；重新整理後需再套用</td></tr><tr><td>原作 Windows 安裝版</td><td>作者的 Windows 中文化工具</td><td>瀏覽器書籤不能直接套在安裝版；先關遊戲並備份</td></tr><tr><td>Mac／Linux 桌面版或其他同名專案</td><td>先查工具作者是否明確支援</td><td>不能把 Windows 安裝指令照搬到別的系統</td></tr><tr><td>本站 Play 窗口</td><td>需要中文化時另開原作，按原作工具說明處理</td><td>本站不在第三方窗口注入補丁；存檔不保證互通</td></tr></tbody></table></div><p>{ext(PATCH,"中文工具作者 · 教學與原下載入口")}。請依自己使用的版本選段落；以上是文件整理，不是本站安裝成功紀錄。{ref(2)}</p>'),
 ('backup','先備份，再動工具或換網站',f'<ol><li>仍能開舊進度時，先在遊戲內儲存並離開，回到主選單。</li><li>開啟 <strong>SAVES</strong>，按該版本的提示匯出 Softcore 存檔檔案或代碼，另存一份不覆蓋的備份。</li><li>若目的地本來也有進度，再單獨匯出目的地備份。匯入會替換目的地，並非合併。</li><li>先完成中文介面檢查，再確認角色與進度。不要為了翻譯清除網站資料。</li></ol><p>原作目前說明 Hardcore 不能匯出／匯入；不要拿 Softcore 的遷移步驟套在它上面。補丁並不是存檔復原服務，跨站、跨版本和桌面遷移未由本站測試。{ref(3)}</p>'),
 ('browser','原作瀏覽器：使用作者的書籤',f'<p>在電腦 Chrome／Edge，依作者頁面把中文書籤按鈕拖到書籤列，再回到原作遊戲頁點該書籤；直接在教學頁點按鈕不是安裝。重新整理後，依作者說明再點書籤。{ref(2)}</p><p>沒反應時，先確認目前分頁是原作遊戲，而不是本站文章或第三方嵌入框；再核對作者最新支援說明。不要為了試翻譯去刪存檔。本文不複製或自動執行書籤程式；請從 {ext(PATCH,"中文工具作者 · 原始教學")} 查看當前版本。</p>'),
 ('windows','Windows：先認安裝版，再看更新與還原',f'<p>作者把 Windows 安裝版另外列為一條路徑：先關閉遊戲，解壓工具，再使用作者提供的中文捷徑；原作自動更新後，翻譯可能需要重新套用。作者也提供移除工具、還原英文的說明。這些操作會改動安裝版的載入方式，並非瀏覽器書籤。{ref(2)}</p><p>只在你確認是作者支援的原作安裝版時考慮這條路線；遇到權限或系統保護提示，先確認來源與檔案，不把本文當作安全認證或關閉防護的建議。仍是英文時，先看啟動捷徑與作者最新說明，再把遊戲版本和錯誤提供給工具作者。本站沒有執行安裝包。</p>'),
 ('mobile','手機教學與原作 FAQ 為何不一致？',f'<p>2026 年 11 月 3 日核對時，原作 FAQ 表示目前不支援手機，並要求玩家自己的 Diablo II 安裝檔。另一方面，10 月 28 日的 Mobile01 分享及中文工具作者列有手機書籤步驟。這些紀錄的時間、版本與檔案供應條件不同，不能合併成「現在手機一定能玩」。{ref(1)}{ref(2)}{ref(4)}</p><p>要穩定開始，優先用電腦開原作並按其當前檔案要求準備。手機能開網頁、能改書籤，不等於當前版本可完成資源準備或開局。本站只做移動尺寸頁面檢查，不宣稱真機相容。</p>'),
 ('limits','中文化與改數值是兩件事',f'<p>工具作者的頁面除了翻譯，也介紹「書籤修改」功能，部分操作會更改遊戲數值或永久進度。只想看中文時，不需要使用那些修改項；翻譯工具的存在不代表所有操作都只改顯示文字。{ref(2)}</p><p>先保留備份，閱讀工具當前說明，再決定是否使用；本文不保證排行榜資格、跨版本相容或工具安全。若你要的是暗黑 II 本體漢化、另一個同名專案或其他網站的存檔，請先回到 #source 的辨認步驟。</p>')]
 toc='<aside class="toc"><strong>本頁內容</strong>'+''.join(f'<a href="#{i}">{t}</a>' for i,t,_ in parts)+'</aside>'
 body=f'<nav class="crumbs"><a href="/">Megabonk.org</a> / D2 Survivors 中文化</nav><header class="article-head" id="guide"><span class="tag">繁體中文 · 非官方任務指南</span><h1>D2 Survivors 中文化：版本、工具與備份</h1><div class="answer"><p>原作目前有英文與韓文；繁體中文工具由玩家另行維護。電腦瀏覽器用作者書籤，原作 Windows 安裝版走另一套工具；先備份，再按你實際使用的版本選路線。本站沒有安裝或驗證補丁成功。</p></div><p class="meta">Megabonk.org 編輯 · 核對 2026-11-03 · 來源整理，非遊玩或安全測試</p></header><div class="article-layout">{toc}<article class="prose">'
 for i,t,c in parts:
  body+=f'<section id="{i}"><h2>{t}</h2>{c}</section>'
  if i=='backup':body+=figure('original-menu','D2 Survivors 原作主選單列出 PLAY、OPTIONS 與 SAVES','原作真實主選單，2026-11-03 擷取；畫面標示 build 20261102.2。SAVES 是備份入口，OPTIONS 是選項入口；這不是中文化成功畫面，也未安裝補丁。遊戲圖像 © Blizzard Entertainment／各權利人。',5)
 body+='<section class="sources" id="sources"><h2>來源與核對範圍</h2><p>原作文件與工具作者各為自己項目的單一來源；有來源材料不代表本站已測過工具、存檔遷移或完整局。</p><ol>'
 for n,(url,label,detail)in enumerate([('https://d2survivors.lol/faq/','D2 Survivors · 原作 FAQ','平台、檔案及語言入口；2026-11-03 核對。'),(PATCH,'GitHub Pages · 中文工具作者','瀏覽器／Windows 路線與額外修改功能；2026-11-03 核對，未下載執行工具。'),('https://d2survivors.lol/wiki/saves/','D2 Survivors · Saves','原作備份與匯入限制；實際版本提示優先。'),('https://www.mobile01.com/topicdetail.php?f=676&p=1&t=7311404','Mobile01 · 酷波分享','2026-10-28 的個人使用分享，非目前手機支援保證。'),(ORIGINAL,'D2 Survivors · 原作遊戲','2026-11-03 主選單擷取，build 20261102.2；只核菜單，不冒稱通關。')],1):body+=f'<li id="source-{n}">{ext(url,label)} — {detail}</li>'
 body+='</ol><a class="back" href="#guide">返回本文 ↑</a></section><section class="related"><h2>下一步</h2><p><a href="/d2-survivors/play/">D2 Survivors · Browser game window →</a></p><p><a href="/azeroth-survivors/">Azeroth Survivors：另一款獨立的幸存者遊戲 →</a></p><p><a href="/#wiki-start">站內相關遊戲 →</a></p></section></article></div>'
 body=body.replace('請先回到 #source 的辨認步驟','請先<a href="#source">確認遊戲來源</a>')
 return shell(ZH,'D2 Survivors 中文化：瀏覽器書籤、Windows 補丁與備份','按原作、瀏覽器與 Windows 安裝版選 D2 Survivors 繁中文化路線，先備份再操作，辨認手機說明衝突及工具限制。',body,'zh-Hant')

def play():
 body=f'''<header class="play-intro" id="guide" data-play-background><p class="play-kicker">D2 SURVIVORS · THIRD-PARTY GAME WINDOW</p><h1>Play D2 Survivors online</h1><p>Choose a Diablo II hero, keep moving and let your skills meet the horde.</p><p>This window uses <strong>play.d2survivors.org</strong>, a third-party edition displaying <strong>20261020.1 during a run</strong> (its menu shows 20261019.1) in our startup check. It is separate from framara’s current original and its saves.</p></header>
<section class="game-panel" id="game-panel" aria-label="D2 Survivors game window" data-mode="normal"><div class="game-screen" id="play"><div class="game-cover" id="game-cover"><img src="/assets/d2-survivors/run-1280.webp" width="1280" height="900" alt="D2 Survivors third-party edition at the start of a survival run"><div class="cover-content"><h2>D2 Survivors</h2><p>One hero. Automatic skills. A growing horde.</p><button class="play-button" id="game-launch" type="button">Play D2 Survivors →</button><p class="cover-note">Click to load play.d2survivors.org.<br>Desktop keyboard recommended.</p></div></div><iframe id="game-frame" title="D2 Survivors third-party browser game" data-src="{GAME}" allow="autoplay; fullscreen; gamepad" allowfullscreen referrerpolicy="strict-origin-when-cross-origin" hidden></iframe></div><div class="game-meta"><p><strong>Separate host, separate progress.</strong> Keep this host and browser profile for this edition. Export a backup in the game before changing websites or versions.</p><div class="game-tools"><button id="game-expand" type="button" aria-pressed="false" disabled>Expand game</button><button id="game-minimize" type="button" aria-expanded="true" aria-controls="play" disabled>Hide game</button>{ext(GAME,'d2survivors.org · open this edition')}{ext(ORIGINAL,'D2 Survivors · original')}</div><p id="game-status" role="status" aria-live="polite">Click Play to connect. Hiding does not pause the game.</p><noscript><p>{ext(GAME,'d2survivors.org · play in its own tab')}</p></noscript></div></section><div class="game-dock" id="game-dock" hidden><span>D2 Survivors hidden</span><button id="game-restore" type="button">Return to game ↑</button></div>
{recommendations('d2-survivors')}
<article class="play-notes" data-play-background><nav class="play-jump" aria-label="On this page"><a href="#start">Start a run</a><a href="#versions">Versions &amp; saves</a><a href="#help">Help</a><a href="#sources">Sources</a></nav><section id="start"><h2>From the title screen to your first run</h2><ol><li>Click Play above and allow the game resources to finish loading. Click the title screen when prompted.</li><li>Choose Play, then a hero using the selection shown by this edition. Read the offered skill cards as you level.</li><li>Move with WASD. Skills attack automatically; use Esc for the pause menu. Click inside the game if movement keys reach the page instead.</li><li>Use the game’s save-and-exit option before leaving. Open SAVES on its main menu to keep a backup where available.</li></ol><p>Expand creates more room. Hide and Return preserve the same game frame; hiding is not pausing. Pause inside the game before reading another guide. Closing this page ends the embedded session. {ref(1)}</p></section>
<section id="versions"><h2>Pick the host before moving your progress</h2><p>The embedded third-party edition is older than the original menu inspected on 3 November 2026 (build 20261102.2). The original’s current FAQ asks for your own Diablo II: Lord of Destruction 1.14 or Diablo II: Resurrected installation; do not assume this hosted edition’s resource setup describes the original. {ref(1)}{ref(2)}</p><p>Each website controls its own storage. Back up both the source and destination before importing anything; an import can replace progress. Current original-game rules distinguish Softcore and Hardcore. Cross-host and cross-version save compatibility has not been tested here. A frame and the same host in a separate tab can also receive different browser storage treatment. {ref(3)}</p><p>Need Chinese text? <a href="{ZH}" lang="zh-Hant">繁體中文化：選版本、工具與備份 →</a>. That guide concerns the original and its community tool, not a patch injected into this window.</p>
{figure('run','D2 Survivors third-party game in a survival run','Third-party browser edition, startup capture on 3 November 2026; run labelled 20261020.1; menu labelled 20261019.1. Game art © Blizzard Entertainment / respective owners. Short startup check, not a full clear or a physical-phone test.',1)}</section>
<section id="help"><h2>If the window does not start</h2><p>Wait for the game’s title/menu rather than treating a loaded frame as a successful start. If it stays blank, open {ext(GAME,'d2survivors.org · same edition in a new tab')}. Keep a note of the host, displayed version and exact message; do not clear saved site data as your first attempt.</p><p>Use a desktop or laptop with a keyboard for this route. The current original FAQ says phones are not supported; a phone-sized page check does not establish game compatibility. {ref(2)} The original also blocks third-party framing, so its link opens externally. We do not proxy it or remove its restrictions.</p><p>This game host and any services it loads control their own data and progress. We cannot read or recover that cross-origin storage. <a href="/privacy-policy#d2-survivors">Read the game-window privacy notice</a>.</p></section><section class="sources" id="sources"><h2>Sources &amp; verification</h2><p>Checked 3 November 2026. Independent guide; not affiliated with the game creators or Blizzard. Third-party game availability and build can change.</p><ol><li id="source-1">{ext(GAME,'d2survivors.org · third-party game')} — actual cross-origin frame and displayed menu inspected; startup and movement checked. No complete run, install, save migration or device benchmark claimed.</li><li id="source-2">{ext('https://d2survivors.lol/faq/','D2 Survivors · original FAQ')} — current original platform and file requirements; a separate edition from this frame.</li><li id="source-3">{ext('https://d2survivors.lol/wiki/saves/','D2 Survivors · original save guide')} — original-game rules; not proof of this older edition’s import compatibility.</li></ol><a class="back" href="#guide">Back to page ↑</a></section></article>'''
 return shell(P+'play/','Play D2 Survivors Online | Browser Game & Save Checks','Play a third-party D2 Survivors browser edition, learn the startup controls and keep its version and saves separate from the original. Find more survivor games.',body,play=True)

def build():
 for route,html in [(ZH,localization()),(P+'play/',play())]:
  f=ROOT/route.lstrip('/')/'index.html';f.parent.mkdir(parents=True,exist_ok=True);write_html(f,html,encoding='utf8')
 f=ROOT/'index.html';text=f.read_text(encoding='utf8')
 if 'id="d2-survivors-tasks"' not in text:
  marker='<div class="route-grid">'
  assert marker in text
  card='<div class="route-card" id="d2-survivors-tasks"><h3>D2 Survivors</h3><p>A Diablo II-inspired survival run. Keep the hosted edition and original saves separate.</p><p><a class="route-link" href="/d2-survivors/play/">Play D2 Survivors →</a></p><p><a class="route-link" href="/d2-survivors/zh/localization/" lang="zh-Hant">繁體中文化：版本與備份 →</a></p></div>'
  write_html(f,text.replace(marker,marker+card,1),encoding='utf8')
 f=ROOT/'privacy-policy.html';text=f.read_text(encoding='utf8')
 if 'id="d2-survivors"' not in text:
  notice='<h2 id="d2-survivors">D2 Survivors task pages and game window</h2><p>Reviewed 3 November 2026. The Play page connects to play.d2survivors.org only after you click Play. This third-party game host and services it uses receive technical request data and control their own storage and progress. Its edition and saves are separate from d2survivors.lol; framed and direct-tab storage can differ. Hiding keeps the frame connected and does not pause the game; close or leave the page to end its session. We cannot read or recover game storage. The localization article links to a community tool externally; we do not install it or upload saves. Ordinary task pages inherit this site’s existing AdSense loader and site-wide Umami analytics described here. Cloudflare hosting and possible performance measurement, including on error responses, are described above.</p>'
  write_html(f,text.replace('</body>',notice+'</body>',1),encoding='utf8')
 print('Built D2 Survivors localization and Play tasks; no game code copied.')
if __name__=='__main__':build()
